CREATE FUNCTION signal_note_report(_filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH selected AS MATERIALIZED(SELECT * FROM signal_filtered(_filter)),scope AS MATERIALIZED(SELECT * FROM signal_filtered(_filter-'from'-'to'-'basis'-'saleId')),valid AS MATERIALIZED(SELECT n.* FROM opportunity_signal_notes n JOIN scope s ON s.id=n.signal_id WHERE signal_note_is_progression(n.note,n.event_type,n.is_progression)),counts AS(SELECT s.id,s.assigned_to,count(n.id) n FROM selected s LEFT JOIN valid n ON n.signal_id=s.id GROUP BY s.id,s.assigned_to),dist AS(SELECT n,count(*) signals FROM counts GROUP BY n),activity AS MATERIALIZED(SELECT n.* FROM valid n WHERE (coalesce(_filter->>'from','')='' OR (n.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date>=(_filter->>'from')::date) AND (coalesce(_filter->>'to','')='' OR (n.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_filter->>'to')::date) AND (coalesce(_filter->>'saleId','')='' OR n.author_id::text=_filter->>'saleId')),assigns AS MATERIALIZED(SELECT e.signal_id,e.detail->>'to' sale,e.created_at starts,lead(e.created_at) OVER(PARTITION BY e.signal_id ORDER BY e.created_at,e.id) ends FROM opportunity_signal_events e JOIN scope s ON s.id=e.signal_id WHERE e.kind='assign'),cycles AS(SELECT a.*,(SELECT min(n.created_at) FROM opportunity_signal_notes n WHERE n.signal_id=a.signal_id AND n.author_id::text=a.sale AND n.status_from='waiting' AND n.status_to IS DISTINCT FROM 'waiting' AND n.created_at>=a.starts AND (a.ends IS NULL OR n.created_at<a.ends)) accepted FROM assigns a WHERE a.sale IS NOT NULL),firsts AS(SELECT c.signal_id,c.sale,c.starts,c.accepted,c.ends,(SELECT min(n.created_at) FROM valid n WHERE n.signal_id=c.signal_id AND n.author_id::text=c.sale AND n.created_at>=c.accepted AND (c.ends IS NULL OR n.created_at<c.ends)) first_note FROM cycles c WHERE c.accepted IS NOT NULL AND (coalesce(_filter->>'from','')='' OR (c.accepted AT TIME ZONE 'Asia/Ho_Chi_Minh')::date>=(_filter->>'from')::date) AND (coalesce(_filter->>'to','')='' OR (c.accepted AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_filter->>'to')::date) AND (coalesce(_filter->>'saleId','')='' OR c.sale=_filter->>'saleId')),portfolio AS(SELECT assigned_to sale,count(*) total,count(*) FILTER(WHERE n=0) zero,count(*) FILTER(WHERE n>0) noted,sum(n) notes,jsonb_object_agg(id,n) signal_counts FROM counts GROUP BY assigned_to),authors AS(SELECT author_id sale,count(*) notes,count(DISTINCT signal_id) signals FROM activity GROUP BY author_id),trend AS(SELECT (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS date_key,count(*) notes FROM activity GROUP BY date_key) SELECT jsonb_build_object('total',(SELECT count(*) FROM counts),'zero',(SELECT count(*) FROM counts WHERE n=0),'noted',(SELECT count(*) FROM counts WHERE n>0),'notes',(SELECT coalesce(sum(n),0) FROM counts),'distribution',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY n) FROM dist d),'[]'),'portfolio',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM portfolio p),'[]'),'activity',coalesce((SELECT jsonb_agg(to_jsonb(a)) FROM authors a),'[]'),'trend',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY date_key) FROM trend t),'[]'),'firsts',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM firsts f),'[]'))$$;
REVOKE ALL ON FUNCTION signal_note_report(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION signal_note_report(jsonb) TO authenticated;